-- Catalog snapshot of the ERP schema, as one JSON document.
-- Run it against production (read-only) to refresh live-catalog.json, and against a
-- fresh database built by scripts/db/build-fresh.sh to compare the two.
-- search_path is emptied so every name in the output is schema-qualified.
set search_path = pg_catalog;
with
ext as (select objid from pg_depend where deptype = 'e'),
pub as (select oid from pg_namespace where nspname = 'public')
select json_build_object(
'enums', (select json_agg(json_build_object('n', t.typname, 'labels', (select json_agg(enumlabel order by enumsortorder) from pg_enum e where e.enumtypid = t.oid)) order by t.typname) from pg_type t where t.typnamespace = (select oid from pub) and t.typtype = 'e'),
'domains', (select json_agg(json_build_object('n', t.typname, 'base', format_type(t.typbasetype, t.typtypmod), 'notnull', t.typnotnull, 'def', t.typdefault, 'checks', (select json_agg(pg_get_constraintdef(c.oid)) from pg_constraint c where c.contypid = t.oid)) order by t.typname) from pg_type t where t.typnamespace = (select oid from pub) and t.typtype = 'd'),
'composites', (select json_agg(json_build_object('n', t.typname, 'cols', (select json_agg(json_build_object('n', a.attname, 't', format_type(a.atttypid, a.atttypmod)) order by a.attnum) from pg_attribute a where a.attrelid = t.typrelid and a.attnum > 0 and not a.attisdropped)) order by t.typname) from pg_type t join pg_class c on c.oid = t.typrelid where t.typnamespace = (select oid from pub) and t.typtype = 'c' and c.relkind = 'c'),
'sequences', (select json_agg(json_build_object('n', c.relname, 'type', format_type(s.seqtypid, null), 'start', s.seqstart::text, 'inc', s.seqincrement::text, 'min', s.seqmin::text, 'max', s.seqmax::text, 'cache', s.seqcache::text, 'cycle', s.seqcycle,
   'owned', (select json_build_object('t', tc.relname, 'c', a.attname) from pg_depend d join pg_class tc on tc.oid = d.refobjid join pg_attribute a on a.attrelid = d.refobjid and a.attnum = d.refobjsubid where d.objid = c.oid and d.classid = 'pg_class'::regclass and d.deptype in ('a', 'i')),
   'identity', exists (select 1 from pg_depend d where d.objid = c.oid and d.deptype = 'i'),
   'acl', c.relacl::text[]) order by c.relname) from pg_class c join pg_sequence s on s.seqrelid = c.oid where c.relnamespace = (select oid from pub) and c.oid not in (select objid from ext)),
'tables', (select json_agg(json_build_object('n', c.relname, 'kind', c.relkind, 'rls', c.relrowsecurity, 'force', c.relforcerowsecurity, 'opts', c.reloptions, 'acl', c.relacl::text[],
   'partkey', case when c.relkind = 'p' then pg_get_partkeydef(c.oid) end,
   'cols', (select json_agg(json_build_object('n', a.attname, 't', format_type(a.atttypid, a.atttypmod), 'nn', a.attnotnull, 'def', pg_get_expr(ad.adbin, ad.adrelid), 'id', a.attidentity, 'gen', a.attgenerated) order by a.attnum) from pg_attribute a left join pg_attrdef ad on ad.adrelid = a.attrelid and ad.adnum = a.attnum where a.attrelid = c.oid and a.attnum > 0 and not a.attisdropped)
 ) order by c.relname) from pg_class c where c.relnamespace = (select oid from pub) and c.relkind in ('r', 'p') and c.oid not in (select objid from ext)),
'constraints', (select json_agg(json_build_object('t', c.relname, 'n', co.conname, 'type', co.contype, 'def', pg_get_constraintdef(co.oid)) order by c.relname, co.contype, co.conname) from pg_constraint co join pg_class c on c.oid = co.conrelid where c.relnamespace = (select oid from pub) and co.contype in ('p', 'u', 'c', 'x', 'f') and c.oid not in (select objid from ext)),
'indexes', (select json_agg(json_build_object('t', c.relname, 'n', i.relname, 'def', pg_get_indexdef(i.oid)) order by c.relname, i.relname) from pg_index x join pg_class i on i.oid = x.indexrelid join pg_class c on c.oid = x.indrelid where c.relnamespace = (select oid from pub) and not exists (select 1 from pg_constraint co where co.conindid = i.oid and co.contype in ('p', 'u', 'x'))),
'views', (select json_agg(json_build_object('n', c.relname, 'kind', c.relkind, 'opts', c.reloptions, 'def', pg_get_viewdef(c.oid), 'acl', c.relacl::text[],
   'deps', (select json_agg(distinct v2.relname) from pg_depend d join pg_rewrite r on r.oid = d.objid join pg_class v2 on v2.oid = d.refobjid where r.ev_class = c.oid and v2.relkind in ('v', 'm') and v2.oid <> c.oid)) order by c.relname) from pg_class c where c.relnamespace = (select oid from pub) and c.relkind in ('v', 'm') and c.oid not in (select objid from ext)),
'triggers', (select json_agg(json_build_object('s', n.nspname, 't', c.relname, 'n', t.tgname, 'def', pg_get_triggerdef(t.oid), 'enabled', t.tgenabled) order by n.nspname, c.relname, t.tgname) from pg_trigger t join pg_class c on c.oid = t.tgrelid join pg_namespace n on n.oid = c.relnamespace join pg_proc p on p.oid = t.tgfoid join pg_namespace pn on pn.oid = p.pronamespace where not t.tgisinternal and (n.nspname = 'public' or pn.nspname = 'public')),
'policies', (select json_agg(json_build_object('s', n.nspname, 't', c.relname, 'n', pol.polname, 'cmd', pol.polcmd, 'perm', pol.polpermissive, 'roles', (select json_agg(case when r = 0 then 'public' else (select rolname from pg_roles where oid = r) end order by 1) from unnest(pol.polroles) r), 'using', pg_get_expr(pol.polqual, pol.polrelid), 'check', pg_get_expr(pol.polwithcheck, pol.polrelid)) order by n.nspname, c.relname, pol.polname) from pg_policy pol join pg_class c on c.oid = pol.polrelid join pg_namespace n on n.oid = c.relnamespace where n.nspname = 'public' or (n.nspname = 'storage' and pol.polname not in ('supabase_internal_placeholder'))),
'functions', (select json_agg(json_build_object('n', p.proname, 'args', pg_get_function_identity_arguments(p.oid), 'kind', p.prokind, 'lang', l.lanname, 'def', pg_get_functiondef(p.oid), 'acl', p.proacl::text[]) order by p.proname, pg_get_function_identity_arguments(p.oid)) from pg_proc p join pg_language l on l.oid = p.prolang where p.pronamespace = (select oid from pub) and p.prokind in ('f', 'p') and p.oid not in (select objid from ext)),
'buckets', (select json_agg(json_build_object('id', id, 'name', name, 'public', public, 'size', file_size_limit, 'mime', allowed_mime_types) order by id) from storage.buckets),
'publication', (select json_agg(json_build_object('pub', pubname, 's', schemaname, 't', tablename) order by pubname, tablename) from pg_publication_tables where schemaname = 'public')
) as catalog;
